9	/// Small OpenAI-style error family used by the minimal HTTP layer.
10	#[derive(Debug, Construct, Macro)]
11	pub enum ApiError {
12	    /// The request is syntactically valid OpenAI JSON but asks for unsupported
13	    /// behavior.
14	    InvalidRequest {
15	        message: String,
16	        param: Option<&'static str>,
17	    },
18	    /// The requested model name does not match the single configured model.
19	    ModelNotFound { model: String },
20	    /// The request body could not be parsed as valid JSON.
21	    JsonParseError { message: String },
22	    /// An unexpected internal failure happened before streaming started.
23	    ServerError { message: String },
24	}
25	
26	impl ApiError {
27	    /// Return the HTTP status code associated with this API error.
28	    pub fn status_code(&self) -> StatusCode {
29	        match self {
30	            Self::InvalidRequest { .. } => StatusCode::BAD_REQUEST,
31	            Self::ModelNotFound { .. } => StatusCode::NOT_FOUND,
32	            Self::ServerError { .. } => StatusCode::INTERNAL_SERVER_ERROR,
33	            Self::JsonParseError { .. } => StatusCode::BAD_REQUEST,
34	        }
35	    }
36	
37	    /// Convert this error into the standard OpenAI-compatible JSON error
38	    /// payload.
39	    pub fn to_error_response(&self) -> ErrorResponse {
40	        let error = match self {
41	            Self::InvalidRequest { message, param } => ErrorDetail {
42	                message: message.clone(),
43	                error_type: "invalid_request_error".to_string(),
44	                param: param.map(|p| p.to_string()),
45	                code: Some("invalid_request_error".to_string()),
46	            },
47	            Self::ModelNotFound { model } => ErrorDetail {
48	                message: format!("The model `{model}` does not exist."),
49	                error_type: "invalid_request_error".to_string(),
50	                param: Some("model".to_string()),
51	                code: Some("model_not_found".to_string()),
52	            },
53	            Self::ServerError { message } => ErrorDetail {
54	                message: message.clone(),
55	                error_type: "server_error".to_string(),
56	                param: None,
57	                code: Some("server_error".to_string()),
58	            },
59	            Self::JsonParseError { message } => ErrorDetail {
60	                message: message.clone(),
61	                error_type: "invalid_request_error".to_string(),
62	                param: None,
63	                code: Some("json_parse_error".to_string()),
64	            },
65	        };
66	
67	        ErrorResponse { error }
68	    }
69	}
70	
71	impl IntoResponse for ApiError {
72	    fn into_response(self) -> Response {
73	        (self.status_code(), Json(self.to_error_response())).into_response()
74	    }
75	}
